// Every symbol goes into the inline registry — see symbolRegistry.tsx for why the
// sprite indirection cannot survive the in-browser export.
registerSymbolMarkup(svgDefsString);

/**
 * Kept mounting for any straggler `<use>` (and for the gallery), but nothing routed
 * through `Icon` or `SymbolSvg` references it any more — those inline the symbol's own
 * markup into the consuming `<svg>` instead.
 */
export const WorkvivoSvgDefs: React.FC = () => (
  <svg
    style={{ display: "none" }}
    dangerouslySetInnerHTML={{ __html: "<defs>" + svgDefsString + "</defs>" }}
  />
);

export const Icon: React.FC<{
  href: string;
  className?: string;
  width?: number | string;
  height?: number | string;
  style?: React.CSSProperties;
}> = ({ href, className = "li", width = 16, height = 16, style }) => (
  <SymbolSvg
    href={href}
    className={className}
    width={width}
    height={height}
    style={style}
  />
);
